Check(hold.Inventory.Items.Sum(i=>i.m_stack)==50,"Full cargo neither deletes nor fabricates resources");
var second=Hold();Check(Clear()==RockClearResult.Cleared&&second.Inventory.Items.Count==1,"Collection uses another available ship hold");
second.InUse=true;Clear();Check(!NativeRock.LastDrop.GetComponent<ZNetView>().Destroyed,"Open cargo hold is not changed by pickup");second.InUse=false;
shipView.Data.InUse=1;Clear();Check(!NativeRock.LastDrop.GetComponent<ZNetView>().Destroyed,"Remote inventory-in-use lock is honored");shipView.Data.InUse=0;
