var scope=second.gameObject.AddComponent<ShipHoldScope>();scope.MigrationBlocked=true;Clear();Check(!NativeRock.LastDrop.GetComponent<ZNetView>().Destroyed,"Unmigrated cargo is never overwritten");scope.MigrationBlocked=false;
second.Inventory.FailPartial=true;int before=second.Inventory.Items.Sum(i=>i.m_stack);Clear();Check(second.Inventory.Items.Sum(i=>i.m_stack)==before&&!NativeRock.LastDrop.GetComponent<ZNetView>().Destroyed,"Partial add failure rolls back and leaves stone available");second.Inventory.FailPartial=false;
var delayed=new GameObject().AddComponent<ItemDrop>();var delayedView=delayed.gameObject.AddComponent<ZNetView>();delayedView.FailDestroy=true;delayed.m_itemData=stone.GetComponent<ItemDrop>().m_itemData.Clone();
Check(RockCargo.Store(ship,player,delayed)&&delayed.m_itemData.m_stack==0&&delayedView.Data.Stack==0,"Delayed network destruction leaves no collectible duplicate stone");
PrivateArea.Allowed=false;int hits=NativeRock.Hits;Check(Clear()==RockClearResult.Blocked&&NativeRock.Hits==hits,"Protected rock is not damaged");PrivateArea.Allowed=true;
rockView.Owner=false;Check(Clear()==RockClearResult.Blocked&&NativeRock.Hits==hits,"Remote-owned rock is not damaged or forcibly claimed");rockView.Owner=true;
ship.Owner=false;Check(Clear()==RockClearResult.NotApplicable,"Non-owner cannot clear or collect");ship.Owner=true;
ship.Aboard=false;Check(Clear()==RockClearResult.NotApplicable,"Player must remain aboard");ship.Aboard=true;
ship.m_shipControlls.User=true;Check(Clear()==RockClearResult.NotApplicable,"Manual helm takeover disables rock clearing");ship.m_shipControlls.User=false;
rockObject.transform.localPosition=new(0,0,10);hits=NativeRock.Hits;Check(Clear()==RockClearResult.Waiting&&NativeRock.Hits==hits,"Karve slows without clearing beyond roughly 9 m reach");rockObject.transform.localPosition=new(0,0,8);
var ore=new GameObject(){name="CopperOre"};ore.AddComponent<ItemDrop>();rock.m_dropItems.m_drops.Add(new(){m_item=ore});Check(Clear()==RockClearResult.NotApplicable,"Mixed stone and ore deposit is not cleared");rock.m_dropItems.m_drops.RemoveAt(1);
rock.name="dungeon_stone";Check(Clear()==RockClearResult.NotApplicable,"Non-rock location prop is not cleared");rock.name="rock_test";
NativeRock.FailAfterDrop=true;before=second.Inventory.Items.Sum(i=>i.m_stack);Check(Clear()==RockClearResult.Blocked&&second.Inventory.Items.Sum(i=>i.m_stack)==before+1,"Native failure still preserves already-created resources");NativeRock.FailAfterDrop=false;
var unrelated=new GameObject().AddComponent<ItemDrop>();unrelated.m_itemData=stone.GetComponent<ItemDrop>().m_itemData.Clone();before=second.Inventory.Items.Sum(i=>i.m_stack);RockClearing.Capture(unrelated);Check(second.Inventory.Items.Sum(i=>i.m_stack)==before,"Unrelated dropped items are never swept into cargo");
rockObject.AddComponent<Piece>();Check(Clear()==RockClearResult.NotApplicable,"Player-built piece is never cleared");
var voyage=shipObject.AddComponent<Voyage>();voyage.Ship=ship;Plugin.Instance.Voyage=voyage;
var fishObject=new GameObject();fishObject.AddComponent<Fish>();var fishCollider=fishObject.AddComponent<BoxCollider>();var otherBoat=new GameObject().AddComponent<BoxCollider>();var rockCollider=new GameObject().AddComponent<BoxCollider>();
Physics.Nearby=new[]{fishCollider,rockCollider,otherBoat};FishCollisionPass.UpdateFor(ship,true);var pass=ship.GetComponent<FishCollisionPass>();pass.Refresh();
Check(Physics.GetIgnoreCollision(ship.m_floatCollider,fishCollider),"Fish-hull collision is ignored during active mode");
Check(!Physics.GetIgnoreCollision(ship.m_floatCollider,rockCollider)&&!Physics.GetIgnoreCollision(ship.m_floatCollider,otherBoat),"Rocks and other boats retain normal collisions");
pass.Restore();Check(!Physics.GetIgnoreCollision(ship.m_floatCollider,fishCollider),"Mode cleanup restores changed collision pairs");
Physics.IgnoreCollision(ship.m_floatCollider,fishCollider,true);pass.Refresh();pass.Restore();Check(Physics.GetIgnoreCollision(ship.m_floatCollider,fishCollider),"Pre-existing collision exclusions are preserved");Physics.IgnoreCollision(ship.m_floatCollider,fishCollider,false);
pass.Refresh();Physics.Nearby=Array.Empty<Collider>();pass.Refresh();Check(!Physics.GetIgnoreCollision(ship.m_floatCollider,fishCollider),"Fish leaving the hull area regain normal collisions");
Physics.Nearby=new[]{fishCollider};pass.Refresh();ship.m_shipControlls.User=true;typeof(FishCollisionPass).GetMethod("Update",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(pass,null);Check(!Physics.GetIgnoreCollision(ship.m_floatCollider,fishCollider),"Manual takeover immediately restores fish collisions");ship.m_shipControlls.User=false;
pass.Refresh();Plugin.Instance.FishPassThrough.Value=false;typeof(FishCollisionPass).GetMethod("Update",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(pass,null);Check(!Physics.GetIgnoreCollision(ship.m_floatCollider,fishCollider),"Disabling the option restores fish collisions");
Console.WriteLine($"PASS: {checks} production rock clearing, stone conservation and fish collision checks.");
